INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_11','V369','阮明',11,'我手机里存了护照复印件照片，可以直接对照填写表格上的全部信息。','wǒ shǒu jī lǐ cún le hù zhào fù yìn jiàn zhào piān， kě yǐ zhí jiē duì zhào tián xiě biǎo gé shàng de quán bù xìn xī。','Trong điện thoại tôi có lưu ảnh chụp bản sao hộ chiếu, có thể đối chiếu để điền đầy đủ thông tin vào mẫu đơn luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_12','V369','民警',12,'笔录填写完毕核对无误后签字，我打印报案回执交给你保管。','bǐ lù tián xiě wán bì hé duì wú wù hòu qiān zì， wǒ dǎ yìn bào àn huí zhí jiāo gěi nǐ bǎo guǎn。','Sau khi điền xong biên bản, đối chiếu không sai sót thì ký tên, tôi sẽ in biên nhận trình báo giao cho bạn giữ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_13','V369','阮明',13,'做完这份遗失笔录，拿着纸质回执就能直接去出入境大厅办理临时通行证件吗？','zuò wán zhè fèn yí shī bǐ lù， ná zhe zhǐ zhì huí zhí jiù néng zhí jiē qù chū rù jìng dà tīng bàn lǐ lín shí tōng xíng zhèng jiàn ma？','Làm xong biên bản mất đồ này, cầm bản giấy biên nhận là có thể đến thẳng phòng xuất nhập cảnh làm giấy tờ đi lại tạm thời được chưa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_14','V369','民警',14,'是的，这份派出所开具的报案回执是外籍人员补办证件必需的官方材料。','shì de， zhè fèn pài chū suǒ kāi jù de bào àn huí zhí shì wài jí rén yuán bǔ bàn zhèng jiàn bì xū de guān fāng cái liào。','Đúng vậy, biên nhận trình báo do đồn công an cấp là giấy tờ chính thức bắt buộc để người nước ngoài làm lại giấy tờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_15','V369','阮明',15,'给警官增添办案工作量实在不好意思，辛苦您帮忙登记备案。','gěi jǐng guān zēng tiān bàn àn gōng zuò liàng shí zài bù hǎo yì sī， xīn kǔ nín bāng máng dēng jì bèi àn。','Làm phiền cảnh sát thêm việc thế này thật ngại quá, cảm ơn anh/chị đã giúp đăng ký hồ sơ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_16','V369','民警',16,'保护外籍留学生证件安全是我们的工作，后续补办遇到问题可以再来咨询。','bǎo hù wài jí liú xué shēng zhèng jiàn ān quán shì wǒ men de gōng zuò， hòu xù bǔ bàn yù dào wèn tí kě yǐ zài lái zī xún。','Bảo vệ giấy tờ an toàn cho du học sinh nước ngoài là công việc của chúng tôi, sau này làm lại giấy tờ có vấn đề gì thì cứ đến hỏi thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_17','V369','阮明',17,'太感谢警官耐心登记信息！','tài gǎn xiè jǐng guān nài xīn dēng jì xìn xī！','Cảm ơn cảnh sát rất nhiều vì đã kiên nhẫn ghi nhận thông tin ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT370','S126','Báo mất ví tiền nơi công cộng',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V370','SIT370','P1','twist','ban_chinh_thuc',NULL,'商场、餐厅等公共场所设有失物招领处，捡到私人物品大多会统一送至前台保管；领取失物需要核对专属标识确认归属。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_01','V370','阮明',1,'你好，我刚才在商场三楼餐饮区用餐，离开后发现黑色钱包丢失，想申请广播寻物。','nǐ hǎo， wǒ gāng cái zài shāng chǎng sān lóu cān yǐn qū yòng cān， lí kāi hòu fā xiàn hēi sè qián bāo diū shī， xiǎng shēn qǐng guǎng bō xún wù。','Chào bạn, tôi vừa ăn ở khu ẩm thực tầng 3 của trung tâm thương mại, ra ngoài thì phát hiện mất cái ví màu đen, muốn nhờ phát thanh tìm đồ giúp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_02','V370','客服',2,'您好，先跟您确认，丢失的钱包里面包含哪些重要物品，方便广播描述特征哦。','nín hǎo， xiān gēn nín què rèn， diū shī de qián bāo lǐ miàn bāo hán nǎ xiē zhòng yào wù pǐn， fāng biàn guǎng bō miáo shù tè zhēng ó。','Chào anh, cho em xác nhận trước, trong ví bị mất có những món đồ quan trọng gì, để tiện mô tả đặc điểm khi phát thanh nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_03','V370','阮明',3,'里面有人民币现金、国内储蓄卡、留学生校园卡，全部对我非常重要。','lǐ miàn yǒu rén mín bì xiàn jīn、 guó nèi chǔ xù kǎ、 liú xué shēng xiào yuán kǎ， quán bù duì wǒ fēi cháng zhòng yào。','Trong đó có tiền mặt VNĐ, à không, tiền nhân dân tệ, thẻ ngân hàng trong nước, và thẻ sinh viên du học, tất cả đều rất quan trọng với tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_04','V370','客服',4,'我现在立刻播放全场寻物广播，麻烦完整描述钱包外观细节，提高捡到者识别概率。','wǒ xiàn zài lì kè bō fàng quán chǎng xún wù guǎng bō， má fán wán zhěng miáo shù qián bāo wài guān xì jié， tí gāo jiǎn dào zhě shí bié gài lǜ。','Em sẽ phát thanh tìm đồ ngay cho toàn khu bây giờ, anh vui lòng mô tả đầy đủ đặc điểm bên ngoài của ví, để tăng khả năng người nhặt được nhận ra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_05','V370','阮明',5,'纯黑色短款皮质钱包，侧面有一道浅色划痕，里面放着越南留学生专属校园卡。','chún hēi sè duǎn kuǎn pí zhì qián bāo， cè miàn yǒu yī dào qiǎn sè huà hén， lǐ miàn fàng zhe yuè nán liú xué shēng zhuān shǔ xiào yuán kǎ。','Ví da ngắn màu đen tuyền, có một vết xước màu nhạt ở mặt bên, bên trong có thẻ sinh viên riêng dành cho du học sinh Việt Nam.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_06','V370','客服',6,'刚好半小时前商场保洁阿姨打扫餐厅，捡到一个黑色钱包送到前台保管，我拿给你核对嘛。','gāng hǎo bàn xiǎo shí qián shāng chǎng bǎo jié ā yí dǎ sǎo cān tīng， jiǎn dào yí gè hēi sè qián bāo sòng dào qián tái bǎo guǎn， wǒ ná gěi nǐ hé duì ma。','Vừa hay nửa tiếng trước cô dọn vệ sinh của trung tâm thương mại lau dọn khu nhà hàng, có nhặt được một cái ví màu đen mang đến quầy lễ tân giữ, để em lấy cho anh đối chiếu nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_07','V370','阮明',7,'真的吗？里面一定会有印有越南国旗标识的留学生校园卡对吧？','zhēn de ma？ lǐ miàn yí dìng huì yǒu yìn yǒu yuè nán guó qí biāo shí de liú xué shēng xiào yuán kǎ duì ba？','Thật hả? Trong đó chắc chắn có thẻ sinh viên in cờ Việt Nam đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_08','V370','客服',8,'没错，钱包内确实有这张校园卡，你当面清点里面所有物品确认齐全再拿走。','méi cuò， qián bāo nèi què shí yǒu zhè zhāng xiào yuán kǎ， nǐ dāng miàn qīng diǎn lǐ miàn suǒ yǒu wù pǐn què rèn qí quán zài ná zǒu。','Đúng vậy, trong ví đúng là có thẻ sinh viên này, anh kiểm đếm trực tiếp toàn bộ đồ bên trong xem có đủ không rồi hãy nhận lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_09','V370','阮明',9,'现金、银行卡、校园卡全部完好，一样东西都没有缺少，太幸运了。','xiàn jīn、 yín háng kǎ、 xiào yuán kǎ quán bù wán hǎo， yī yàng dōng xī dōu méi yǒu quē shǎo， tài xìng yùn le。','Tiền mặt, thẻ ngân hàng, thẻ sinh viên đều còn nguyên vẹn, không thiếu món nào cả, may quá đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_10','V370','客服',10,'商场所有拾获私人物品都会统一送至前台失物招领处登记保管。','shāng chǎng suǒ yǒu shí huò sī rén wù pǐn dōu huì tǒng yī sòng zhì qián tái shī wù zhāo lǐng chù dēng jì bǎo guǎn。','Tất cả đồ nhặt được của khách trong trung tâm thương mại đều được gom về quầy lễ tân để đăng ký và bảo quản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_11','V370','阮明',11,'还好保洁阿姨细心捡到上交，不然补办银行卡、证件要耗费大量时间。','hái hǎo bǎo jié ā yí xì xīn jiǎn dào shàng jiāo， bù rán bǔ bàn yín háng kǎ、 zhèng jiàn yào hào fèi dà liàng shí jiān。','May mà cô dọn vệ sinh cẩn thận nhặt được rồi nộp lại, không thì làm lại thẻ ngân hàng, giấy tờ sẽ tốn rất nhiều thời gian.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_12','V370','客服',12,'下次出门贵重物品尽量贴身放好，避免遗失。','xià cì chū mén guì zhòng wù pǐn jǐn liàng tiē shēn fàng hǎo， bì miǎn yí shī。','Lần sau ra ngoài anh nhớ để đồ có giá trị sát người nhé, tránh bị mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_13','V370','阮明',13,'我记住了，非常感谢你们帮忙妥善保管我的钱包。','wǒ jì zhù le， fēi cháng gǎn xiè nǐ men bāng máng tuǒ shàn bǎo guǎn wǒ de qián bāo。','Tôi nhớ rồi, cảm ơn các bạn rất nhiều vì đã giúp giữ ví cẩn thận cho tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_14','V370','客服',14,'不用客气，这是我们商场该做的。','bù yòng kè qì， zhè shì wǒ men shāng chǎng gāi zuò de。','Không có gì đâu ạ, đây là việc trung tâm thương mại nên làm mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_15','V370','阮明',15,'麻烦各位工作人员了！','má fán gè wèi gōng zuò rén yuán le！','Làm phiền các nhân viên nhiều quá!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT371','S126','Báo mất điện thoại, xin khóa SIM từ xa',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V371','SIT371','P1','suon_se','chinh_thuc',NULL,'手机丢失后可致电运营商紧急挂失SIM卡，补办卡片可保留原有手机号，不会更换号码；首次挂失补卡大多免除工本费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_01','V371','阮明',1,'您好，紧急求助，我的手机外出遗失，需要立刻远程锁定本人电话SIM卡。','nín hǎo， jǐn jí qiú zhù， wǒ de shǒu jī wài chū yí shī， xū yào lì kè yuǎn chéng suǒ dìng běn rén diàn huà SIM kǎ。','Chào bạn, tôi có việc khẩn cấp cần hỗ trợ, điện thoại của tôi bị mất khi ra ngoài, cần khóa SIM từ xa ngay lập tức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_02','V371','客服',2,'您好，为完成挂失锁卡操作，需要核实实名登记的全部身份信息，请您配合。','nín hǎo， wèi wán chéng guà shī suǒ kǎ cāo zuò， xū yào hé shí shí míng dēng jì de quán bù shēn fèn xìn xī， qǐng nín pèi hé。','Chào anh, để hoàn tất thao tác báo mất và khóa SIM, cần xác minh toàn bộ thông tin danh tính đã đăng ký chính chủ, mong anh phối hợp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_03','V371','阮明',3,'我清楚实名核验流程，您需要什么信息我全部如实报给您核对。','wǒ qīng chǔ shí míng hé yàn liú chéng， nín xū yào shén me xìn xī wǒ quán bù rú shí bào gěi nín hé duì。','Tôi hiểu quy trình xác minh chính chủ, bạn cần thông tin gì tôi sẽ cung cấp đầy đủ để đối chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_04','V371','客服',4,'依次提供遗失手机号、实名登记姓名、本人护照完整编号吧。','yī cì tí gōng yí shī shǒu jī hào、 shí míng dēng jì xìng míng、 běn rén hù zhào wán zhěng biān hào ba。','Anh vui lòng cung cấp lần lượt: số điện thoại bị mất, họ tên đã đăng ký chính chủ, và số hộ chiếu đầy đủ của anh.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_05','V371','阮明',5,'手机号、姓名、护照号码我全部记录在备忘录，现在逐条念给您。','shǒu jī hào、 xìng míng、 hù zhào hào mǎ wǒ quán bù jì lù zài bèi wàng lù， xiàn zài zhú tiáo niàn gěi nín。','Số điện thoại, họ tên, số hộ chiếu tôi đều lưu trong ghi chú, để tôi đọc từng mục cho bạn nghe ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_06','V371','客服',6,'信息核验全部匹配，系统已经完成紧急挂失锁卡，他人无法使用你的号码呢。','xìn xī hé yàn quán bù pǐ pèi， xì tǒng yǐ jīng wán chéng jǐn jí guà shī suǒ kǎ， tā rén wú fǎ shǐ yòng nǐ de hào mǎ ne。','Thông tin xác minh đều khớp hết, hệ thống đã hoàn tất khóa SIM khẩn cấp, người khác sẽ không thể dùng số của anh nữa đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_07','V371','阮明',7,'锁卡之后手机里绑定的支付软件、社交账号就不会被盗刷盗用了对吗？','suǒ kǎ zhī hòu shǒu jī lǐ bǎng dìng de zhī fù ruǎn jiàn、 shè jiāo zhàng hào jiù bú huì bèi dào shuā dào yòng le duì ma？','Sau khi khóa SIM thì các ứng dụng thanh toán, tài khoản mạng xã hội liên kết trong điện thoại sẽ không bị đánh cắp hay lợi dụng đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_08','V371','客服',8,'SIM卡锁定后无法接收验证码，能最大程度保护你的账户、资金安全。','SIM kǎ suǒ dìng hòu wú fǎ jiē shōu yàn zhèng mǎ， néng zuì dà chéng dù bǎo hù nǐ de zhàng hù、 zī jīn ān quán。','Sau khi SIM bị khóa thì không thể nhận mã xác nhận nữa, việc này sẽ bảo vệ tài khoản và tiền của anh ở mức tối đa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_09','V371','阮明',9,'挂失锁卡只是临时冻结，后续补办新卡还能保留原来的手机号码吗？','guà shī suǒ kǎ zhǐ shì lín shí dòng jié， hòu xù bǔ bàn xīn kǎ hái néng bǎo liú yuán lái de shǒu jī hào mǎ ma？','Báo mất và khóa SIM chỉ là đóng băng tạm thời, sau này làm lại SIM mới thì có giữ được số điện thoại cũ không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_10','V371','客服',10,'完全可以，携带本人护照前往线下任意营业厅就能补办同号SIM卡。','wán quán kě yǐ， xié dài běn rén hù zhào qián wǎng xiàn xià rèn yì yíng yè tīng jiù néng bǔ bàn tóng hào SIM kǎ。','Hoàn toàn được, anh chỉ cần mang hộ chiếu đến bất kỳ cửa hàng giao dịch nào là có thể làm lại SIM giữ nguyên số.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_11','V371','阮明',11,'补办卡片需要额外支付工本费，还是免费办理？','bǔ bàn kǎ piàn xū yào é wài zhī fù gōng běn fèi， hái shì miǎn fèi bàn lǐ？','Làm lại SIM có phải trả thêm phí làm thẻ không, hay là làm miễn phí?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_12','V371','客服',12,'首次挂失补卡免收工本费，一年内多次补卡才会收取卡片费用。','shǒu cì guà shī bǔ kǎ miǎn shōu gōng běn fèi， yī nián nèi duō cì bǔ kǎ cái huì shōu qǔ kǎ piàn fèi yòng。','Lần đầu báo mất và làm lại SIM thì miễn phí, chỉ khi làm lại nhiều lần trong một năm mới bị tính phí thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_13','V371','阮明',13,'清楚全部规则了，太感谢您第一时间帮我冻结手机号。','qīng chǔ quán bù guī zé le， tài gǎn xiè nín dì yī shí jiān bāng wǒ dòng jié shǒu jī hào。','Tôi hiểu hết các quy định rồi, cảm ơn bạn rất nhiều vì đã giúp tôi khóa số điện thoại kịp thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_14','V371','客服',14,'后续补办有任何疑问，随时拨打官方客服热线咨询。','hòu xù bǔ bàn yǒu rèn hé yí wèn， suí shí bō dǎ guān fāng kè fú rè xiàn zī xún。','Sau này làm lại SIM có thắc mắc gì thì cứ gọi đường dây nóng chăm sóc khách hàng chính thức để hỏi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_15','V371','阮明',15,'多亏及时挂失，避免财产受损，十分感谢！','duō kuī jí shí guà shī， bì miǎn cái chǎn shòu sǔn， shí fēn gǎn xiè！','May mà báo mất kịp thời, tránh bị thiệt hại tài sản, cảm ơn rất nhiều!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT372','S126','Gọi số cấp cứu khi có người bị thương',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V372','SIT372','P1','suon_se','chinh_thuc',NULL,'国内急救电话120免费拨打，接线员会同步指导简单急救措施，并快速调配就近医院车辆；伤者骨折、出血不可随意挪动，防止二次伤害。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_01','V372','阮明',1,'您好，这里发生人员摔倒受伤事故，情况紧急，麻烦尽快派遣救护车过来啊！','nín hǎo， zhè lǐ fā shēng rén yuán shuāi dǎo shòu shāng shì gù， qíng kuàng jǐn jí， má fán jǐn kuài pài qiǎn jiù hù chē guò lái a！','Alo, ở đây có người bị té ngã bị thương, tình hình khẩn cấp lắm, làm ơn điều xe cứu thương đến gấp giúp tôi với!','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_02','V372','接线员',2,'请先保持冷静，不要慌乱，分步骤告知我精准地址与伤者详细状况吧。','qǐng xiān bǎo chí lěng jìng， bú yào huāng luàn， fēn bù zhòu gào zhī wǒ jīng zhǔn dì zhǐ yǔ shāng zhě xiáng xì zhuàng kuàng ba。','Anh bình tĩnh lại, đừng hoảng, cho tôi biết địa chỉ chính xác và tình trạng người bị thương theo từng bước nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_03','V372','阮明',3,'事发地点在大学南门沿街小吃街，伤者下楼梯摔倒，腿部大面积出血，暂时无法自主站立呢。','shì fā dì diǎn zài dà xué nán mén yán jiē xiǎo chī jiē， shāng zhě xià lóu tī shuāi dǎo， tuǐ bù dà miàn jī chū xiě， zàn shí wú fǎ zì zhǔ zhàn lì ne。','Chỗ xảy ra sự việc là khu phố ăn vặt ở cổng nam trường đại học, người bị thương té ngã khi xuống cầu thang, chân chảy máu nhiều, tạm thời không tự đứng dậy được.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_04','V372','接线员',4,'现场千万不要随意挪动、拖拽伤者，避免造成二次骨骼损伤，医护人员十分钟内抵达现场。','xiàn chǎng qiān wàn bú yào suí yì nuó dòng、 tuō zhuāi shāng zhě， bì miǎn zào chéng èr cì gǔ gé sǔn shāng， yī hù rén yuán shí fēn zhōng nèi dǐ dá xiàn chǎng。','Tuyệt đối không được tự ý di chuyển, kéo lê người bị thương, tránh gây tổn thương xương thêm lần nữa, nhân viên y tế sẽ có mặt trong vòng 10 phút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_05','V372','阮明',5,'我会守在路口显眼位置等候救护车，指引医护车辆快速找到事发点位。','wǒ huì shǒu zài lù kǒu xiǎn yǎn wèi zhì děng hòu jiù hù chē， zhǐ yǐn yī hù chē liàng kuài sù zhǎo dào shì fā diǎn wèi。','Tôi sẽ đứng ở vị trí dễ thấy ở đầu đường để đợi xe cứu thương, chỉ đường cho xe y tế nhanh chóng tìm đến đúng chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_06','V372','接线员',6,'全程保持通话畅通，如果伤者出血量变大、意识模糊，立刻同步告知我。','quán chéng bǎo chí tōng huà chàng tōng， rú guǒ shāng zhě chū xiě liàng biàn dà、 yì shí mó hú， lì kè tóng bù gào zhī wǒ。','Giữ liên lạc điện thoại xuyên suốt nhé, nếu người bị thương chảy máu nhiều hơn hoặc lơ mơ thì báo cho tôi ngay lập tức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_07','V372','阮明',7,'我随身带纸巾按压伤口止血，暂时没有出现意识不清的情况。','wǒ suí shēn dài zhǐ jīn àn yā shāng kǒu zhǐ xuè， zàn shí méi yǒu chū xiàn yì shí bù qīng de qíng kuàng。','Tôi có mang khăn giấy theo người để ấn cầm máu vết thương, tạm thời chưa thấy có dấu hiệu lơ mơ mất tỉnh táo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_08','V372','接线员',8,'医护抵达前持续按压出血部位，减少血液流失。','yī hù dǐ dá qián chí xù àn yā chū xiě bù wèi， jiǎn shǎo xuè yè liú shī。','Trước khi nhân viên y tế đến thì cứ tiếp tục ấn giữ chỗ chảy máu, để giảm mất máu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_09','V372','阮明',9,'我会严格按照您的指引简单处理伤口，不擅自移动伤者。','wǒ huì yán gé àn zhào nín de zhǐ yǐn jiǎn dān chǔ lǐ shāng kǒu， bù shàn zì yí dòng shāng zhě。','Tôi sẽ làm đúng theo hướng dẫn của bạn để sơ cứu vết thương đơn giản, không tự ý di chuyển người bị thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_10','V372','接线员',10,'救护车已经驶出医院，距离现场还有三分钟路程。','jiù hù chē yǐ jīng shǐ chū yī yuàn， jù lí xiàn chǎng hái yǒu sān fēn zhōng lù chéng。','Xe cứu thương đã xuất phát từ bệnh viện rồi, còn cách hiện trường khoảng 3 phút nữa thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_11','V372','阮明',11,'我现在站在校门口马路边挥手示意车辆。','wǒ xiàn zài zhàn zài xiào mén kǒu mǎ lù biān huī shǒu shì yì chē liàng。','Tôi đang đứng ở bên đường trước cổng trường vẫy tay ra hiệu cho xe rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_12','V372','接线员',12,'辛苦你现场协助看护伤者，医护马上抵达。','xīn kǔ nǐ xiàn chǎng xié zhù kān hù shāng zhě， yī hù mǎ shàng dǐ dá。','Cảm ơn anh đã hỗ trợ trông chừng người bị thương tại chỗ, nhân viên y tế sắp đến nơi rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_13','V372','阮明',13,'好的，我全程在这里等候，辛苦你们火速赶来！','hǎo de， wǒ quán chéng zài zhè lǐ děng hòu， xīn kǔ nǐ men huǒ sù gǎn lái！','Được rồi, tôi sẽ đợi ở đây suốt, mong mọi người đến thật nhanh nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT373','S126','Báo cháy nhỏ trong khu bếp chung ký túc',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V373','SIT373','P1','twist','ban_chinh_thuc',NULL,'油锅起火严禁浇水，正确方式为隔绝氧气盖锅盖；国内宿舍厨房明令禁止无人看管明火，无人值守属于违规行为。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_01','V373','阮明',1,'宿管老师，紧急跟您汇报，宿舍楼公共厨房炒锅起火，我已经第一时间关闭燃气总阀。','sù guǎn lǎo shī， jǐn jí gēn nín huì bào， sù shè lóu gōng gòng chú fáng chǎo guō qǐ huǒ， wǒ yǐ jīng dì yī shí jiān guān bì rán qì zǒng fá。','Cô quản lý ơi, con báo gấp với cô, chảo trong bếp chung của ký túc xá bị cháy, con đã khóa van gas tổng ngay lập tức rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_02','V373','宿管老师',2,'你先远离起火厨具，我先确认一件事，有没有直接用水浇灭锅里的火源嘛？','nǐ xiān yuǎn lí qǐ huǒ chú jù， wǒ xiān què rèn yī jiàn shì， yǒu méi yǒu zhí jiē yòng shuǐ jiāo miè guō lǐ de huǒ yuán ma？','Con tránh xa dụng cụ đang cháy đã, cô hỏi con một việc trước, con có dội nước thẳng vào lửa trong chảo không vậy?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_03','V373','阮明',3,'我之前上过宿舍安全培训，牢记油锅起火不能浇水，立刻拿锅盖完整盖住锅体隔绝氧气灭火。','wǒ zhī qián shàng guò sù shè ān quán péi xùn， láo jì yóu guō qǐ huǒ bù néng jiāo shuǐ， lì kè ná guō gài wán zhěng gài zhù guō tǐ gé jué yǎng qì miè huǒ。','Con có học qua khóa tập huấn an toàn ký túc xá rồi, con nhớ kỹ là chảo dầu bốc cháy không được dội nước, con lấy nắp vung đậy kín chảo lại để cách ly oxy dập lửa ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_04','V373','宿管老师',4,'还好你掌握正确灭火方法，没有盲目泼水引发火势扩散，我现在携带灭火器赶往厨房。','hái hǎo nǐ zhǎng wò zhèng què miè huǒ fāng fǎ， méi yǒu máng mù pō shuǐ yǐn fā huǒ shì kuò sàn， wǒ xiàn zài xié dài miè huǒ qì gǎn wǎng chú fáng。','May mà con biết cách dập lửa đúng, không dội nước bừa làm lửa lan rộng, cô mang bình chữa cháy đến bếp ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_05','V373','阮明',5,'明火已经完全熄灭，只是墙面瓷砖被烟火轻微熏黑，没有蔓延到周边厨具、橱柜对吧？','míng huǒ yǐ jīng wán quán xī miè， zhǐ shì qiáng miàn cí zhuān bèi yān huǒ qīng wēi xūn hēi， méi yǒu màn yán dào zhōu biān chú jù、 chú guì duì ba？','Lửa đã tắt hoàn toàn rồi ạ, chỉ có gạch tường bị ám khói đen nhẹ thôi, không lan sang các dụng cụ, tủ bếp xung quanh đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_06','V373','宿管老师',6,'只要没有引燃橱柜、纸巾等易燃物品，就不算重大火情，仅轻微安全隐患。','zhǐ yào méi yǒu yǐn rán chú guì、 zhǐ jīn děng yì rán wù pǐn， jiù bù suàn zhòng dà huǒ qíng， jǐn qīng wēi ān quán yǐn huàn。','Chỉ cần không bén lửa sang tủ bếp, khăn giấy hay các thứ dễ cháy khác thì không tính là hỏa hoạn nghiêm trọng, chỉ là nguy cơ an toàn nhỏ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_07','V373','阮明',7,'这次起火是我熬汤忘记看管，离开几分钟汤水烧干才引燃锅底，是我的疏忽。','zhè cì qǐ huǒ shì wǒ áo tāng wàng jì kān guǎn， lí kāi jǐ fēn zhōng tāng shuǐ shāo gàn cái yǐn rán guō dǐ， shì wǒ de shū hū。','Lần này cháy là do con nấu canh mà quên trông, đi có mấy phút thì nước cạn làm cháy đáy nồi, là lỗi bất cẩn của con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_08','V373','宿管老师',8,'宿舍公共厨房明确规定明火烹饪必须有人全程看管，无人值守极易引发火灾。','sù shè gōng gòng chú fáng míng què guī dìng míng huǒ pēng rèn bì xū yǒu rén quán chéng kān guǎn， wú rén zhí shǒu jí yì yǐn fā huǒ zāi。','Quy định bếp chung ký túc xá đã nói rõ nấu bằng lửa phải có người trông chừng suốt, không có ai canh rất dễ gây cháy nổ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_09','V373','阮明',9,'我深刻记住这条安全规定，之后做饭绝不擅自离开灶台半步。','wǒ shēn kè jì zhù zhè tiáo ān quán guī dìng， zhī hòu zuò fàn jué bù shàn zì lí kāi zào tái bàn bù。','Con ghi nhớ kỹ quy định an toàn này rồi, sau này nấu ăn con nhất định không rời khỏi bếp nửa bước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_10','V373','宿管老师',10,'我到现场检查残留隐患，确认无复燃风险之后再通知大家使用厨房。','wǒ dào xiàn chǎng jiǎn chá cán liú yǐn huàn， què rèn wú fù rán fēng xiǎn zhī hòu zài tōng zhī dà jiā shǐ yòng chú fáng。','Cô sẽ đến hiện trường kiểm tra các nguy cơ còn sót lại, xác nhận không có khả năng cháy lại rồi mới thông báo cho mọi người dùng bếp lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_11','V373','阮明',11,'需要我留在厨房配合您清点厨具、说明起火全过程吗？','xū yào wǒ liú zài chú fáng pèi hé nín qīng diǎn chú jù、 shuō míng qǐ huǒ quán guò chéng ma？','Con có cần ở lại bếp để phối hợp với cô kiểm đếm dụng cụ, kể lại toàn bộ quá trình cháy không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_12','V373','宿管老师',12,'你可以在值班室等候，检查完毕我会跟你说明后续注意事项。','nǐ kě yǐ zài zhí bān shì děng hòu， jiǎn chá wán bì wǒ huì gēn nǐ shuō míng hòu xù zhù yì shì xiàng。','Con cứ đợi ở phòng trực, kiểm tra xong cô sẽ nói cho con biết những điều cần lưu ý tiếp theo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_13','V373','阮明',13,'给老师带来安全巡查的额外工作，实在抱歉。','gěi lǎo shī dài lái ān quán xún chá de é wài gōng zuò， shí zài bào qiàn。','Làm phiền cô phải đi kiểm tra an toàn thêm việc, con thật sự xin lỗi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_14','V373','宿管老师',14,'吸取教训就好，安全第一不用过度自责。','xī qǔ jiào xùn jiù hǎo， ān quán dì yī bù yòng guò dù zì zé。','Rút kinh nghiệm là được rồi, an toàn là trên hết, con không cần tự trách quá mức đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_15','V373','阮明',15,'我之后做饭一定时刻留意火源，不会再出现这种情况。','wǒ zhī hòu zuò fàn yí dìng shí kè liú yì huǒ yuán， bú huì zài chū xiàn zhè zhǒng qíng kuàng。','Sau này nấu ăn con nhất định sẽ luôn để ý lửa, sẽ không để xảy ra chuyện này nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT374','S126','Trình báo tai nạn giao thông nhẹ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V374','SIT374','P1','suon_se','chinh_thuc',NULL,'无人员伤亡的轻微交通事故，可通过交管平台线上处理，无需等待交警到场；外籍当事人护照可作为辅助身份凭证上传备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_01','V374','阮明',1,'您好，城市主干道十字路口发生两车轻微剐蹭，事故双方均无人员受伤。','nín hǎo， chéng shì zhǔ gàn dào shí zì lù kǒu fā shēng liǎng chē qīng wēi guǎ cèng， shì gù shuāng fāng jūn wú rén yuán shòu shāng。','Alo, tại ngã tư đường chính trong thành phố vừa xảy ra va quẹt nhẹ giữa hai xe, cả hai bên đều không có ai bị thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_02','V374','交警接线员',2,'先做好两件事，第一双方车辆挪至路边非机动车道，第二多角度拍摄完整现场照片留存证据吧。','xiān zuò hǎo liǎng jiàn shì， dì yī shuāng fāng chē liàng nuó zhì lù biān fēi jī dòng chē dào， dì èr duō jiǎo dù pāi shè wán zhěng xiàn chǎng zhào piān liú cún zhèng jù ba。','Anh làm ngay hai việc này giúp tôi nhé: một là đưa cả hai xe vào làn không dành cho xe cơ giới ven đường, hai là chụp ảnh hiện trường đầy đủ từ nhiều góc để làm bằng chứng.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_03','V374','阮明',3,'我们已经共同把车辆停靠在不阻碍主路通行的非机动车道，前后、侧面、碰撞位置都拍好了多角度现场照片呢。','wǒ men yǐ jīng gòng tóng bǎ chē liàng tíng kào zài bù zǔ ài zhǔ lù tōng xíng de fēi jī dòng chē dào， qián hòu、 cè miàn、 pèng zhuàng wèi zhì dōu pāi hǎo le duō jiǎo dù xiàn chǎng zhào piān ne。','Chúng tôi đã cùng nhau đưa xe vào làn không cản trở giao thông chính rồi, đã chụp đầy đủ ảnh hiện trường từ phía trước, bên hông, và vị trí va chạm ở nhiều góc độ rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_04','V374','接线员',4,'无人员伤亡、仅轻微车身剐蹭的小型事故，可通过交管线上平台快速定责，不需要交警线下现场出警。','wú rén yuán shāng wáng、 jǐn qīng wēi chē shēn guǎ cèng de xiǎo xíng shì gù， kě tōng guò jiāo guǎn xiàn shàng píng tái kuài sù dìng zé， bù xū yào jiāo jǐng xiàn xià xiàn chǎng chū jǐng。','Với vụ va chạm nhỏ không có thương vong, chỉ trầy xước thân xe nhẹ thì có thể xử lý phân định trách nhiệm nhanh qua nền tảng trực tuyến của cảnh sát giao thông, không cần cảnh sát đến hiện trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_05','V374','阮明',5,'线上平台处理事故，需要上传哪些证件照片，外籍留学生的护照可以作为有效证件使用吗？','xiàn shàng píng tái chǔ lǐ shì gù， xū yào shàng chuán nǎ xiē zhèng jiàn zhào piān， wài jí liú xué shēng de hù zhào kě yǐ zuò wéi yǒu xiào zhèng jiàn shǐ yòng ma？','Xử lý trên nền tảng trực tuyến thì cần tải lên ảnh giấy tờ gì, hộ chiếu của du học sinh nước ngoài có được dùng làm giấy tờ hợp lệ không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_06','V374','接线员',6,'需要上传机动车行驶证、驾驶员驾驶证，外加当事人护照照片，全部拍照上传系统即可。','xū yào shàng chuán jī dòng chē xíng shǐ zhèng、 jià shǐ yuán jià shǐ zhèng， wài jiā dāng shì rén hù zhào zhào piān， quán bù pāi zhào shàng chuán xì tǒng jí kě。','Cần tải lên giấy đăng ký xe, bằng lái xe của tài xế, cộng thêm ảnh hộ chiếu của người liên quan, chụp ảnh tải hết lên hệ thống là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_07','V374','阮明',7,'定责完成之后，理赔流程也是直接在线上操作，不用前往交警大队线下办理？','dìng zé wán chéng zhī hòu， lǐ péi liú chéng yě shì zhí jiē zài xiàn shàng cāo zuò， bù yòng qián wǎng jiāo jǐng dà duì xiàn xià bàn lǐ？','Sau khi phân định trách nhiệm xong, quy trình bồi thường cũng làm trực tuyến luôn, không cần đến đội cảnh sát giao thông giải quyết trực tiếp phải không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_08','V374','接线员',8,'全责方保险公司线上对接理赔，全程线上办结，省去线下跑腿时间。','quán zé fāng bǎo xiǎn gōng sī xiàn shàng duì jiē lǐ péi， quán chéng xiàn shàng bàn jié， shěng qù xiàn xià pǎo tuǐ shí jiān。','Công ty bảo hiểm của bên chịu toàn bộ trách nhiệm sẽ kết nối bồi thường trực tuyến, xử lý xong hết trên mạng, không cần đi lại trực tiếp mất thời gian.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_09','V374','阮明',9,'我现在和对方车主整理全部证件照片，马上上传交管小程序。','wǒ xiàn zài hé duì fāng chē zhǔ zhěng lǐ quán bù zhèng jiàn zhào piān， mǎ shàng shàng chuán jiāo guǎn xiǎo chéng xù。','Tôi đang cùng chủ xe bên kia tổng hợp toàn bộ ảnh giấy tờ, sẽ tải lên ứng dụng của cảnh sát giao thông ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_10','V374','接线员',10,'上传完成等待系统自动分配交警线上审核，半小时内出具责任认定书。','shàng chuán wán chéng děng dài xì tǒng zì dòng fēn pèi jiāo jǐng xiàn shàng shěn hé， bàn xiǎo shí nèi chū jù zé rèn rèn dìng shū。','Tải lên xong thì đợi hệ thống tự động phân công cảnh sát duyệt trực tuyến, trong vòng nửa tiếng sẽ có văn bản xác định trách nhiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_11','V374','阮明',11,'清楚完整线上处理流程，不用耽误双方过多时间。','qīng chǔ wán zhěng xiàn shàng chǔ lǐ liú chéng， bù yòng dān wù shuāng fāng guò duō shí jiān。','Tôi đã hiểu rõ toàn bộ quy trình xử lý trực tuyến rồi, sẽ không làm mất thời gian của hai bên nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_12','V374','接线员',12,'后续理赔有纠纷，可再次拨打交警热线咨询。','hòu xù lǐ péi yǒu jiū fēn， kě zài cì bō dǎ jiāo jǐng rè xiàn zī xún。','Sau này nếu bồi thường có tranh chấp gì thì có thể gọi lại đường dây nóng cảnh sát giao thông để hỏi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_13','V374','阮明',13,'感谢您清晰告知线上快速处理流程！','gǎn xiè nín qīng xī gào zhī xiàn shàng kuài sù chǔ lǐ liú chéng！','Cảm ơn bạn đã giải thích rõ ràng quy trình xử lý nhanh trực tuyến!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT375','S126','Trình báo bị lừa chuyển tiền qua mạng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V375','SIT375','P1','twist','chinh_thuc',NULL,'遭遇网络诈骗第一时间联系反诈中心冻结对方账户，再线下报案，是国内标准维权流程；完整聊天、转账截图是关键办案证据，不可删除。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_01','V375','阮明',1,'您好，我遭到网络虚假客服诱导转账，资金已经成功转入对方陌生账户，前来求助拦截。','nín hǎo， wǒ zāo dào wǎng luò xū jiǎ kè fú yòu dǎo zhuǎn zhàng， zī jīn yǐ jīng chéng gōng zhuǎn rù duì fāng mò shēng zhàng hù， qián lái qiú zhù lán jié。','Chào bạn, tôi bị một dịch vụ chăm sóc khách hàng giả mạo lừa chuyển tiền, số tiền đã chuyển thành công vào tài khoản lạ của bên kia, tôi đến nhờ hỗ trợ chặn lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_02','V375','反诈客服',2,'请立刻提供三项关键信息，对方收款账号、精确转账时间、完整转账金额哈。','qǐng lì kè tí gōng sān xiàng guān jiàn xìn xī， duì fāng shōu kuǎn zhàng hào、 jīng què zhuǎn zhàng shí jiān、 wán zhěng zhuǎn zhàng jīn é hā。','Anh cung cấp ngay 3 thông tin quan trọng giúp em: số tài khoản nhận tiền của bên kia, thời gian chuyển tiền chính xác, và số tiền chuyển đầy đủ nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_03','V375','阮明',3,'我刚刚完成转账立刻察觉对方是骗子，想要操作转账撤回功能却系统提示失败嘛。','wǒ gāng gāng wán chéng zhuǎn zhàng lì kè chá jué duì fāng shì piàn zi， xiǎng yào cāo zuò zhuǎn zhàng chè huí gōng néng què xì tǒng tí shì shī bài ma。','Tôi vừa chuyển xong là phát hiện ngay bên kia là lừa đảo, muốn thao tác hủy giao dịch thì hệ thống báo lỗi không thực hiện được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_04','V375','反诈客服',4,'资金一旦成功转入私人第三方账户，无法由用户自主撤回，我现在紧急提交账户冻结指令。','zī jīn yí dàn chéng gōng zhuǎn rù sī rén dì sān fāng zhàng hù， wú fǎ yóu yòng hù zì zhǔ chè huí， wǒ xiàn zài jǐn jí tí jiāo zhàng hù dòng jié zhǐ lìng。','Một khi tiền đã chuyển thành công vào tài khoản cá nhân của bên thứ ba thì người dùng không thể tự hủy được, em sẽ gửi lệnh khẩn cấp phong tỏa tài khoản ngay bây giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_05','V375','阮明',5,'账户冻结之后，我转出的资金还有机会拦截追回，避免全部损失吗？','zhàng hù dòng jié zhī hòu， wǒ zhuǎn chū de zī jīn hái yǒu jī huì lán jié zhuī huí， bì miǎn quán bù sǔn shī ma？','Sau khi phong tỏa tài khoản, số tiền tôi đã chuyển có còn cơ hội chặn lại và lấy về được không, để tránh mất trắng?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_06','V375','反诈客服',6,'冻结对方账户可以锁住未被转出的资金，后续需要你到辖区派出所完成报案笔录留存证据。','dòng jié duì fāng zhàng hù kě yǐ suǒ zhù wèi bèi zhuǎn chū de zī jīn， hòu xù xū yào nǐ dào xiá qū pài chū suǒ wán chéng bào àn bǐ lù liú cún zhèng jù。','Phong tỏa tài khoản bên kia sẽ giữ lại được phần tiền chưa bị chuyển đi tiếp, sau đó anh cần đến đồn công an nơi cư trú để làm biên bản trình báo lưu lại bằng chứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_07','V375','阮明',7,'请问报案的派出所地址在哪里，办理笔录需要携带什么证件？','qǐng wèn bào àn de pài chū suǒ dì zhǐ zài nǎ lǐ， bàn lǐ bǐ lù xū yào xié dài shén me zhèng jiàn？','Cho tôi hỏi đồn công an để trình báo ở đâu vậy, làm biên bản cần mang theo giấy tờ gì?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_08','V375','反诈客服',8,'携带本人护照前往就近辖区派出所，工作人员会同步对接反诈中心留存线索。','xié dài běn rén hù zhào qián wǎng jiù jìn xiá qū pài chū suǒ， gōng zuò rén yuán huì tóng bù duì jiē fǎn zhà zhōng xīn liú cún xiàn suǒ。','Anh mang theo hộ chiếu đến đồn công an gần nơi cư trú nhất, nhân viên ở đó sẽ kết nối với trung tâm phòng chống lừa đảo để lưu manh mối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_09','V375','阮明',9,'笔录做完提交线索，警方会持续跟进追查诈骗账户吗？','bǐ lù zuò wán tí jiāo xiàn suǒ， jǐng fāng huì chí xù gēn jìn zhuī chá zhà piàn zhàng hù ma？','Làm biên bản và nộp manh mối xong, cảnh sát có tiếp tục theo dõi truy tìm tài khoản lừa đảo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_10','V375','反诈客服',10,'警方会登记全部涉案线索，持续追踪资金流向，尽力挽回群众损失。','jǐng fāng huì dēng jì quán bù shè àn xiàn suǒ， chí xù zhuī zōng zī jīn liú xiàng， jìn lì wǎn huí qún zhòng sǔn shī。','Cảnh sát sẽ ghi nhận toàn bộ manh mối liên quan đến vụ án, tiếp tục truy dấu dòng tiền, cố gắng hết sức để giúp người dân giảm thiệt hại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_11','V375','阮明',11,'我现在记下派出所地址，立刻动身前往线下登记报案。','wǒ xiàn zài jì xià pài chū suǒ dì zhǐ， lì kè dòng shēn qián wǎng xiàn xià dēng jì bào àn。','Tôi ghi lại địa chỉ đồn công an rồi, sẽ đi ngay để trình báo trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_12','V375','反诈客服',12,'路上保管好转账截图、聊天记录等全部证据，不要删除。','lù shàng bǎo guǎn hǎo zhuǎn zhàng jié tú、 liáo tiān jì lù děng quán bù zhèng jù， bú yào shān chú。','Trên đường đi anh nhớ giữ lại ảnh chụp màn hình chuyển tiền, lịch sử trò chuyện và mọi bằng chứng khác, đừng xóa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_13','V375','阮明',13,'所有聊天、转账记录我都完整保存，不会丢失。','suǒ yǒu liáo tiān、 zhuǎn zhàng jì lù wǒ dōu wán zhěng bǎo cún， bú huì diū shī。','Toàn bộ tin nhắn, lịch sử chuyển tiền tôi đều lưu đầy đủ, sẽ không bị mất đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_14','V375','反诈客服',14,'后续案件进展派出所会同步通知你。','hòu xù àn jiàn jìn zhǎn pài chū suǒ huì tóng bù tōng zhī nǐ。','Sau này có tiến triển gì về vụ án thì đồn công an sẽ thông báo cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_15','V375','阮明',15,'感谢紧急冻结对方账户，降低我的财产损失！','gǎn xiè jǐn jí dòng jié duì fāng zhàng hù， jiàng dī wǒ de cái chǎn sǔn shī！','Cảm ơn đã khẩn cấp phong tỏa tài khoản bên kia, giúp tôi giảm bớt thiệt hại tài sản!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT376','S126','Báo khóa cửa phòng bị hỏng, không vào được phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V376','SIT376','P1','suon_se','ban_chinh_thuc',NULL,'出租公寓门锁自然老化损坏，物业免费上门维修；租客人为撬动、暴力损坏门锁，则需自行支付配件与工时费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_01','V376','阮明',1,'物业您好，我租住公寓的入户门锁出现故障，钥匙插入锁孔完全转动不开，无法进门。','wù yè nín hǎo， wǒ zū zhù gōng yù de rù hù mén suǒ chū xiàn gù zhàng， yào shi chā rù suǒ kǒng wán quán zhuǎn dòng bù kāi， wú fǎ jìn mén。','Chào bên quản lý tòa nhà, khóa cửa căn hộ tôi đang thuê bị hỏng, tra chìa vào ổ khóa mà không xoay được, không vào nhà được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_02','V376','维修专员',2,'先跟我确认，你尝试转动钥匙的时候，有没有暴力掰扯、大力敲击门锁？','xiān gēn wǒ què rèn， nǐ cháng shì zhuǎn dòng yào shi de shí hòu， yǒu méi yǒu bào lì bāi chě、 dà lì qiāo jī mén suǒ？','Cho em xác nhận trước, lúc anh xoay chìa khóa có dùng lực mạnh vặn hay đập mạnh vào ổ khóa không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_03','V376','阮明',3,'我只是平稳插入钥匙左右轻转，没有用力掰动锁芯，不存在人为破坏的情况。','wǒ zhǐ shì píng wěn chā rù yào shi zuǒ yòu qīng zhuǎn， méi yǒu yòng lì bāi dòng suǒ xīn， bù cún zài rén wéi pò huài de qíng kuàng。','Tôi chỉ tra chìa vào nhẹ nhàng rồi xoay qua xoay lại thôi, không có dùng lực vặn lõi khóa, không có chuyện cố ý làm hỏng gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_04','V376','维修专员',4,'你先到楼下单元门禁处等候，我携带全套维修工具，十分钟之内抵达楼栋哦。','nǐ xiān dào lóu xià dān yuán mén jìn chù děng hòu， wǒ xié dài quán tào wéi xiū gōng jù， shí fēn zhōng zhī nèi dǐ dá lóu dòng ó。','Anh xuống chờ ở cửa ra vào tòa nhà bên dưới nhé, em mang đầy đủ dụng cụ sửa chữa, khoảng 10 phút nữa sẽ có mặt tại tòa nhà.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_05','V376','阮明',5,'锁芯内部完全卡死，我尝试家里三把备用钥匙，全部都没办法转动开门呢。','suǒ xīn nèi bù wán quán kǎ sǐ， wǒ cháng shì jiā lǐ sān bǎ bèi yòng yào shi， quán bù dōu méi bàn fǎ zhuǎn dòng kāi mén ne。','Lõi khóa bên trong bị kẹt cứng hoàn toàn, tôi thử cả 3 chìa dự phòng ở nhà đều không xoay mở được luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_06','V376','维修专员',6,'大概率是锁芯内部金属零件老化断裂，这种自然老化故障需要直接更换整套门锁。','dà gài lǜ shì suǒ xīn nèi bù jīn shǔ líng jiàn lǎo huà duàn liè， zhè zhǒng zì rán lǎo huà gù zhàng xū yào zhí jiē gēng huàn zhěng tào mén suǒ。','Nhiều khả năng là bộ phận kim loại bên trong lõi khóa bị lão hóa gãy rồi, kiểu hỏng do lão hóa tự nhiên thế này thì phải thay nguyên bộ khóa mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_07','V376','阮明',7,'更换整套门锁产生的配件费、人工费，是由我租房住户自行承担吗？','gēng huàn zhěng tào mén suǒ chǎn shēng de pèi jiàn fèi、 rén gōng fèi， shì yóu wǒ zū fáng zhù hù zì xíng chéng dān ma？','Chi phí phụ kiện, tiền công để thay nguyên bộ khóa mới, có phải do người thuê nhà như tôi tự chi trả không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_08','V376','维修专员',8,'区分损坏原因，房屋设施自然老化损坏由物业全额免费上门维修；租客人为损坏才需要自费支付配件工时费。','qū fēn sǔn huài yuán yīn， fáng wū shè shī zì rán lǎo huà sǔn huài yóu wù yè quán é miǎn fèi shàng mén wéi xiū； zū kè rén wéi sǔn huài cái xū yào zì fèi zhī fù pèi jiàn gōng shí fèi。','Còn tùy nguyên nhân hư hỏng ạ: nếu thiết bị nhà cửa hỏng do lão hóa tự nhiên thì bên quản lý sẽ đến sửa miễn phí hoàn toàn; còn nếu người thuê làm hỏng thì mới phải tự trả phí phụ kiện và công thợ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_09','V376','阮明',9,'全程轻柔试钥匙，没有磕碰、撬动门锁，属于自然老化故障对吧？','quán chéng qīng róu shì yào shi， méi yǒu kē pèng、 qiào dòng mén suǒ， shǔ yú zì rán lǎo huà gù zhàng duì ba？','Suốt quá trình tôi chỉ thử chìa nhẹ nhàng thôi, không va đập hay cạy khóa gì cả, vậy là thuộc trường hợp lão hóa tự nhiên đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_10','V376','维修专员',10,'抵达现场查看锁体磨损情况后判定，自然老化无需你支付任何费用。','dǐ dá xiàn chǎng chá kàn suǒ tǐ mó sǔn qíng kuàng hòu pàn dìng， zì rán lǎo huà wú xū nǐ zhī fù rèn hé fèi yòng。','Đến hiện trường xem mức độ mòn của ổ khóa rồi mới xác định được, nếu đúng là lão hóa tự nhiên thì anh không phải trả bất kỳ khoản phí nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_11','V376','阮明',11,'我在楼下门禁处安静等候，麻烦您尽快过来检修门锁。','wǒ zài lóu xià mén jìn chù ān jìng děng hòu， má fán nín jǐn kuài guò lái jiǎn xiū mén suǒ。','Tôi đang đợi yên ở cửa ra vào tòa nhà bên dưới, làm phiền bạn đến sửa khóa sớm giúp tôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_12','V376','维修专员',12,'马上出发，到楼下我给你打电话。','mǎ shàng chū fā， dào lóu xià wǒ gěi nǐ dǎ diàn huà。','Em xuất phát ngay đây, xuống đến nơi em sẽ gọi điện cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_13','V376','阮明',13,'辛苦专员专程上门处理故障，耽误您工作时间实在不好意思。','xīn kǔ zhuān yuán zhuān chéng shàng mén chǔ lǐ gù zhàng， dān wù nín gōng zuò shí jiān shí zài bù hǎo yì sī。','Cảm ơn bạn kỹ thuật đã vất vả đến tận nơi xử lý sự cố, làm mất thời gian làm việc của bạn thật ngại quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_14','V376','维修专员',14,'房屋维修是物业本职工作，不用客气。','fáng wū wéi xiū shì wù yè běn zhí gōng zuò， bù yòng kè qì。','Sửa chữa nhà cửa là công việc chính của bên quản lý mà, anh không cần khách sáo đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_15','V376','阮明',15,'十分感谢，我在这里等您！','shí fēn gǎn xiè， wǒ zài zhè lǐ děng nín！','Cảm ơn rất nhiều, tôi sẽ đợi bạn ở đây!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT377','S126','Xin cấp lại giấy tờ tạm thời khi mất hộ chiếu',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V377','SIT377','P1','twist','chinh_thuc',NULL,'外籍留学生护照丢失后，出入境大厅可开具临时通行证明，用于回国或补办护照；现场自助拍照符合涉外证件标准，无需提前线下照相馆拍摄。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_01','V377','阮明',1,'您好，本人越南护照不慎遗失，前来大厅申请临时出入境通行证明。','nín hǎo， běn rén yuè nán hù zhào bù shèn yí shī， qián lái dà tīng shēn qǐng lín shí chū rù jìng tōng xíng zhèng míng。','Chào chị, tôi là công dân Việt Nam, do sơ ý làm mất hộ chiếu nên đến quầy xin cấp giấy phép xuất nhập cảnh tạm thời ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_02','V377','工作人员',2,'办理临时通行证明需要两份核心材料，派出所开具的遗失报案回执、标准一寸白底证件照片吧。','bàn lǐ lín shí tōng xíng zhèng míng xū yào liǎng fèn hé xīn cái liào， pài chū suǒ kāi jù de yí shī bào àn huí zhí、 biāo zhǔn yī cùn bái dǐ zhèng jiàn zhào piān ba。','Để làm giấy thông hành tạm thời thì cần hai loại giấy tờ chính: biên nhận trình báo mất giấy tờ do công an phường cấp, và một tấm ảnh thẻ 3x4 nền trắng đúng chuẩn.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_03','V377','阮明',3,'派出所出具的遗失回执我已经随身携带，但是出门匆忙，没有提前准备一寸白底证件照嘛。','pài chū suǒ chū jù de yí shī huí zhí wǒ yǐ jīng suí shēn xié dài， dàn shì chū mén cōng máng， méi yǒu tí qián zhǔn bèi yī cùn bái dǐ zhèng jiàn zhào ma。','Biên nhận trình báo mất của công an phường thì tôi mang theo sẵn rồi, nhưng vì đi vội quá nên chưa chuẩn bị trước ảnh thẻ nền trắng.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_04','V377','工作人员',4,'大厅大厅入口设有自助拍照机，专门办理涉外证件拍摄，一套照片收费二十元。','dà tīng dà tīng rù kǒu shè yǒu zì zhù pāi zhào jī， zhuān mén bàn lǐ shè wài zhèng jiàn pāi shè， yī tào zhào piān shōu fèi èr shí yuán。','Ở lối vào sảnh có máy chụp ảnh tự động, chuyên chụp ảnh cho giấy tờ dành cho người nước ngoài, một bộ ảnh giá hai mươi tệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_05','V377','阮明',5,'现场拍摄完证件照片，当天递交全部材料就能直接拿到临时通行证件吗？','xiàn chǎng pāi shè wán zhèng jiàn zhào piān， dàng tiān dì jiāo quán bù cái liào jiù néng zhí jiē ná dào lín shí tōng xíng zhèng jiàn ma？','Chụp ảnh xong tại chỗ rồi, nộp đầy đủ giấy tờ trong ngày thì có thể nhận giấy thông hành tạm thời luôn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_06','V377','工作人员',6,'只要回执、照片、护照信息全部材料齐全，窗口当场办结出证，无需等候。','zhǐ yào huí zhí、 zhào piān、 hù zhào xìn xī quán bù cái liào qí quán， chuāng kǒu dāng chǎng bàn jié chū zhèng， wú xū děng hòu。','Chỉ cần đủ biên nhận, ảnh, và thông tin hộ chiếu là được giải quyết và cấp giấy ngay tại quầy, không cần chờ đợi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_07','V377','阮明',7,'这份临时通行证明有效期多长时间，能用来回国补办正式护照吗？','zhè fèn lín shí tōng xíng zhèng míng yǒu xiào qī duō zhǎng shí jiān， néng yòng lái huí guó bǔ bàn zhèng shì hù zhào ma？','Giấy thông hành tạm thời này có hiệu lực bao lâu, có thể dùng để về nước làm lại hộ chiếu chính thức không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_08','V377','工作人员',8,'临时证明有效期三十天，可用于搭乘国际航班出境，也能前往驻华大使馆补办护照。','lín shí zhèng míng yǒu xiào qī sān shí tiān， kě yòng yú dā chéng guó jì háng bān chū jìng， yě néng qián wǎng zhù huá dà shǐ guǎn bǔ bàn hù zhào。','Giấy tạm thời có hiệu lực ba mươi ngày, có thể dùng để lên chuyến bay quốc tế xuất cảnh, và cũng có thể đến đại sứ quán để làm lại hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_09','V377','阮明',9,'那我先去自助拍照机拍摄证件照，拍完立刻返回窗口提交全部材料。','nà wǒ xiān qù zì zhù pāi zhào jī pāi shè zhèng jiàn zhào， pāi wán lì kè fǎn huí chuāng kǒu tí jiāo quán bù cái liào。','Vậy tôi qua máy chụp ảnh tự động chụp ảnh thẻ trước, chụp xong sẽ quay lại quầy nộp đủ giấy tờ ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_10','V377','工作人员',10,'拍照后记得核对人像清晰度，不合格需要重新拍摄。','pāi zhào hòu jì de hé duì rén xiàng qīng xī dù， bù hé gé xū yào chóng xīn pāi shè。','Chụp ảnh xong nhớ kiểm tra độ nét của khuôn mặt nhé, nếu không đạt thì phải chụp lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_11','V377','阮明',11,'我会仔细检查照片标准，不耽误窗口办理流程。','wǒ huì zǐ xì jiǎn chá zhào piàn biāo zhǔn， bù dān wù chuāng kǒu bàn lǐ liú chéng。','Tôi sẽ kiểm tra kỹ tiêu chuẩn ảnh, không làm chậm quy trình xử lý ở quầy đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_12','V377','工作人员',12,'拍完直接到三号窗口递交材料即可。','pāi wán zhí jiē dào sān hào chuāng kǒu dì jiāo cái liào jí kě。','Chụp xong thì mang thẳng đến quầy số ba để nộp giấy tờ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_13','V377','阮明',13,'感谢工作人员清晰告知全部办理步骤！','gǎn xiè gōng zuò rén yuán qīng xī gào zhī quán bù bàn lǐ bù zhòu！','Cảm ơn anh/chị đã hướng dẫn rõ ràng toàn bộ các bước làm thủ tục!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT378','S126','Liên hệ đại sứ quán khi gặp sự cố nghiêm trọng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V378','SIT378','P1','suon_se','chinh_thuc',NULL,'外籍公民在中国发生重大人身意外，可联系本国驻华大使馆获取领事协助，包含对接家属、证件补办、事故手续协调等服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_01','V378','阮明',1,'您好，我是在华就读的越南留学生，途中遭遇严重交通事故，紧急寻求使馆协助。','nín hǎo， wǒ shì zài huá jiù dú de yuè nán liú xué shēng， tú zhōng zāo yù yán zhòng jiāo tōng shì gù， jǐn jí xún qiú shǐ guǎn xié zhù。','Xin chào, tôi là du học sinh Việt Nam đang học tại Trung Quốc, tôi vừa gặp một vụ tai nạn giao thông nghiêm trọng trên đường, khẩn cấp cần sự hỗ trợ của đại sứ quán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_02','V378','接线员',2,'请你先保持冷静，逐条告知我你的完整姓名、就读院校、事故精确详细地点呢。','qǐng nǐ xiān bǎo chí lěng jìng， zhú tiáo gào zhī wǒ nǐ de wán zhěng xìng míng、 jiù dú yuàn xiào、 shì gù jīng què xiáng xì dì diǎn ne。','Bạn hãy bình tĩnh trước đã, cho tôi biết lần lượt họ tên đầy đủ, trường đang học, và địa điểm xảy ra tai nạn chính xác nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_03','V378','阮明',3,'我叫阮明，本市高校汉语言专业留学生，事故发生在市中心主干道十字路口，交警与救护车已经抵达现场处置。','wǒ jiào ruǎn míng， běn shì gāo xiào hàn yǔ yán zhuān yè liú xué shēng， shì gù fā shēng zài shì zhōng xīn zhǔ gàn dào shí zì lù kǒu， jiāo jǐng yǔ jiù hù chē yǐ jīng dǐ dá xiàn chǎng chǔ zhì。','Tôi tên là Nguyễn Minh, là du học sinh chuyên ngành tiếng Trung tại một trường đại học ở đây, vụ tai nạn xảy ra ở ngã tư trên trục đường chính trung tâm thành phố, cảnh sát giao thông và xe cứu thương đã có mặt xử lý.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_04','V378','接线员',4,'我们会第一时间同步联系当地辖区交警大队跟进本次事故完整处置流程，后续协助处理各类手续。','wǒ men huì dì yī shí jiān tóng bù lián xì dāng dì xiá qū jiāo jǐng dà duì gēn jìn běn cì shì gù wán zhěng chǔ zhì liú chéng， hòu xù xié zhù chǔ lǐ gè lèi shǒu xù。','Chúng tôi sẽ liên hệ ngay với đội cảnh sát giao thông khu vực để theo sát toàn bộ quá trình xử lý vụ việc này, và sẽ hỗ trợ các thủ tục liên quan tiếp theo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_05','V378','阮明',5,'后续治疗、证件补办、对接国内家属等全部相关事宜，都能寻求大使馆提供领事协助吧？','hòu xù zhì liáo、 zhèng jiàn bǔ bàn、 duì jiē guó nèi jiā shǔ děng quán bù xiāng guān shì yí， dōu néng xún qiú dà shǐ guǎn tí gōng lǐng shì xié zhù ba？','Những việc như điều trị sau này, làm lại giấy tờ, liên lạc với người thân trong nước, đều có thể nhờ đại sứ quán hỗ trợ lãnh sự đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_06','V378','接线员',6,'是的，所有境外公民在中国遭遇重大人身意外，本国驻华大使馆均会提供全套领事协助服务。','shì de， suǒ yǒu jìng wài gōng mín zài zhōng guó zāo yù zhòng dà rén shēn yì wài， běn guó zhù huá dà shǐ guǎn jūn huì tí gōng quán tào lǐng shì xié zhù fú wù。','Đúng vậy, mọi công dân nước ngoài gặp sự cố nghiêm trọng tại Trung Quốc đều sẽ được đại sứ quán nước mình hỗ trợ lãnh sự đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_07','V378','阮明',7,'现在伤者正在接受医护检查，暂时无法确认伤情轻重，有新情况我会再次致电汇报。','xiàn zài shāng zhě zhèng zài jiē shòu yī hù jiǎn chá， zàn shí wú fǎ què rèn shāng qíng qīng zhòng， yǒu xīn qíng kuàng wǒ huì zài cì zhì diàn huì bào。','Hiện người bị thương đang được kiểm tra y tế, tạm thời chưa xác định được mức độ nặng nhẹ, có thông tin mới tôi sẽ gọi lại báo cáo ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_08','V378','接线员',8,'记下这条官方联系热线，后续任何手续难题随时来电咨询。','jì xià zhè tiáo guān fāng lián xì rè xiàn， hòu xù rèn hé shǒu xù nán tí suí shí lái diàn zī xún。','Bạn ghi lại số đường dây nóng chính thức này, sau này có vướng mắc gì về thủ tục thì cứ gọi đến hỏi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_09','V378','阮明',9,'我会保存热线号码，有需要第一时间联系使馆工作人员。','wǒ huì bǎo cún rè xiàn hào mǎ， yǒu xū yào dì yī shí jiān lián xì shǐ guǎn gōng zuò rén yuán。','Tôi sẽ lưu lại số đường dây nóng, cần gì sẽ liên hệ ngay với nhân viên đại sứ quán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_10','V378','接线员',10,'祝你平安，有进展及时沟通。','zhù nǐ píng ān， yǒu jìn zhǎn jí shí gōu tōng。','Chúc bạn bình an, có tiến triển gì thì báo lại kịp thời nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_11','V378','阮明',11,'太感谢使馆提供应急协助，缓解我的慌乱。','tài gǎn xiè shǐ guǎn tí gōng yìng jí xié zhù， huǎn jiě wǒ de huāng luàn。','Cảm ơn đại sứ quán rất nhiều vì đã hỗ trợ khẩn cấp, giúp tôi đỡ hoang mang hẳn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT379','S127','Viết CV xin việc làm thêm bán thời gian',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V379','SIT379','P1','twist','tuy_y',NULL,'国内兼职简历注重简洁清晰，留学生求职必须标注在校合法务工资质，方便用人单位审核。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_01','V379','阮明',1,'溪溪，我想写简历申请中文助教兼职，不知道怎么排版啊。','xī xī， wǒ xiǎng xiě jiǎn lì shēn qǐng zhōng wén zhù jiào jiān zhí， bù zhī dào zěn me pái bǎn a。','Khê Khê ơi, tớ muốn viết CV xin làm trợ giảng tiếng Trung bán thời gian mà chẳng biết trình bày sao cho ổn.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_02','V379','林溪',2,'简历分基础信息、语言能力、实践经历三大块就行啦。','jiǎn lì fēn jī chǔ xìn xī、 yǔ yán néng lì、 shí jiàn jīng lì sān dà kuài jiù xíng la。','Chia CV thành ba phần thông tin cơ bản, năng lực ngôn ngữ, kinh nghiệm thực tế là được rồi mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_03','V379','阮明',3,'留学生需要额外标注签证和合法打工证明吗？','liú xué shēng xū yào é wài biāo zhù qiān zhèng hé hé fǎ dǎ gōng zhèng míng ma？','Du học sinh có cần ghi thêm visa với giấy tờ chứng minh làm việc hợp pháp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_04','V379','林溪',4,'一定要写，很多商家不清楚留学生打工规定呢。','yí dìng yào xiě， hěn duō shāng jiā bù qīng chǔ liú xué shēng dǎ gōng guī dìng ne。','Phải ghi chứ, nhiều chỗ chẳng rành quy định làm thêm của du học sinh đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_05','V379','阮明',5,'我写完一份草稿，里面实践经历写得太简单。','wǒ xiě wán yī fèn cǎo gǎo， lǐ miàn shí jiàn jīng lì xiě dé tài jiǎn dān。','Tớ viết xong một bản nháp rồi, mà phần kinh nghiệm thực tế viết sơ sài quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_06','V379','林溪',6,'没关系，发给我，我帮你修改补充细节。','méi guān xì， fā gěi wǒ， wǒ bāng nǐ xiū gǎi bǔ chōng xì jié。','Không sao, gửi cho tớ, tớ giúp cậu sửa với bổ sung chi tiết cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_07','V379','阮明',7,'太谢谢你，改完我就能直接投递岗位。','tài xiè xiè nǐ， gǎi wán wǒ jiù néng zhí jiē tóu dì gǎng wèi。','Cảm ơn cậu nhiều lắm, sửa xong là tớ nộp hồ sơ luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT380','S127','Trả lời phỏng vấn xin việc làm thêm',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V380','SIT380','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职面试注重实操能力与空闲时间匹配度，面试官一般会在三日内统一反馈录用结果。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_01','V380','阮明',1,'主管您好，我是阮明，今天来面试少儿汉语助教兼职。','zhǔ guǎn nín hǎo， wǒ shì ruǎn míng， jīn tiān lái miàn shì shào ér hàn yǔ zhù jiào jiān zhí。','Chào quản lý, em là Nguyễn Minh, hôm nay đến phỏng vấn vị trí trợ giảng tiếng Trung thiếu nhi bán thời gian ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_02','V380','主管',2,'请坐，先简单介绍一下你的语言水平和空闲时间吧。','qǐng zuò， xiān jiǎn dān jiè shào yī xià nǐ de yǔ yán shuǐ píng hé kòng xián shí jiān ba。','Mời ngồi, em giới thiệu sơ qua về trình độ ngôn ngữ và thời gian rảnh của mình xem nào.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_03','V380','阮明',3,'我汉语日常交流流利，工作日傍晚和周末全天有空呢。','wǒ hàn yǔ rì cháng jiāo liú liú lì， gōng zuò rì bàng wǎn hé zhōu mò quán tiān yǒu kòng ne。','Em giao tiếp tiếng Trung hàng ngày khá trôi chảy, các buổi tối trong tuần và cả ngày cuối tuần em đều rảnh ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_04','V380','主管',4,'你有和小朋友相处的相关经验，擅长课堂互动吗？','nǐ yǒu hé xiǎo péng yǒu xiāng chǔ de xiāng guān jīng yàn， shàn cháng kè táng hù dòng ma？','Em có kinh nghiệm gì trong việc tiếp xúc với trẻ nhỏ không, có giỏi tương tác trong lớp học không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_05','V380','阮明',5,'我之前在校园活动带过低龄学生，很喜欢和孩子沟通。','wǒ zhī qián zài xiào yuán huó dòng dài guò dī líng xué shēng， hěn xǐ huān hé hái zi gōu tōng。','Trước đây em từng dẫn dắt các bạn nhỏ tuổi trong các hoạt động ở trường, em rất thích trò chuyện với trẻ con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_06','V380','主管',6,'整体条件符合岗位需求，三天内通知你入职结果。','zhěng tǐ tiáo jiàn fú hé gǎng wèi xū qiú， sān tiān nèi tōng zhī nǐ rù zhí jié guǒ。','Nhìn chung điều kiện của em phù hợp với vị trí này, trong ba ngày sẽ báo kết quả nhận việc cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_07','V380','阮明',7,'感谢您给予面试机会，我耐心等候通知。','gǎn xiè nín jǐ yǔ miàn shì jī huì， wǒ nài xīn děng hòu tōng zhī。','Cảm ơn anh/chị đã cho em cơ hội phỏng vấn, em sẽ kiên nhẫn chờ tin ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT381','S127','Ký hợp đồng lao động thời vụ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V381','SIT381','P1','twist','chinh_thuc',NULL,'国内兼职临时用工必须签署劳务合同，薪资、加班、离职相关条款全部需要白纸黑字标注。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_01','V381','阮明',1,'您好，这份临时劳务合同我仔细看完，有一处想确认。','nín hǎo， zhè fèn lín shí láo wù hé tóng wǒ zǐ xì kàn wán， yǒu yī chù xiǎng què rèn。','Chào chị, tôi đã xem kỹ bản hợp đồng lao động tạm thời này rồi, có một chỗ muốn xác nhận lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_02','V381','人事专员',2,'你对哪一条条款有疑问，直接提出来就可以哈。','nǐ duì nǎ yī tiáo tiáo kuǎn yǒu yí wèn， zhí jiē tí chū lái jiù kě yǐ hā。','Bạn thắc mắc điều khoản nào thì cứ nói thẳng ra nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_03','V381','阮明',3,'合同标注每月二十号发薪，但是没有写明加班补贴标准嘛。','hé tóng biāo zhù měi yuè èr shí hào fā xīn， dàn shì méi yǒu xiě míng jiā bān bǔ tiē biāo zhǔn ma。','Hợp đồng ghi trả lương vào ngày hai mươi hàng tháng, nhưng lại không nêu rõ mức phụ cấp làm thêm giờ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_04','V381','人事专员',4,'加班薪资细则附在合同补充页，我拿给你核对。','jiā bān xīn zī xì zé fù zài hé tóng bǔ chōng yè， wǒ ná gěi nǐ hé duì。','Chi tiết về lương làm thêm giờ được đính kèm ở trang bổ sung của hợp đồng, tôi đưa cho bạn xem lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_05','V381','阮明',5,'补充条款签字之后，两份合同双方各留存一份对吧？','bǔ chōng tiáo kuǎn qiān zì zhī hòu， liǎng fèn hé tóng shuāng fāng gè liú cún yī fèn duì ba？','Sau khi ký điều khoản bổ sung, hai bên mỗi bên giữ một bản hợp đồng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_06','V381','人事专员',6,'没错，一份门店存档，一份由你本人保管。','méi cuò， yī fèn mén diàn cún dàng， yī fèn yóu nǐ běn rén bǎo guǎn。','Đúng vậy, một bản lưu tại cửa hàng, một bản do bạn tự giữ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_07','V381','阮明',7,'清楚全部条款，我现在签字确认。','qīng chǔ quán bù tiáo kuǎn， wǒ xiàn zài qiān zì què rèn。','Tôi đã rõ hết các điều khoản rồi, giờ tôi ký xác nhận luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT382','S127','Xin nghỉ làm vì trùng giờ thi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V382','SIT382','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职允许学生因学业请假，门店会灵活调整排班，不会随意克扣薪资；学生备考类请假大多可以协调同事顶替，无需自行补工时。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_01','V382','阮明',1,'店长您好，有一件事提前跟您沟通，下周三我无法到门店上班。','diàn zhǎng nín hǎo， yǒu yī jiàn shì tí qián gēn nín gōu tōng， xià zhōu sān wǒ wú fǎ dào mén diàn shàng bān。','Chào quản lý, có việc này em muốn báo trước với anh/chị, thứ Tư tuần sau em không thể đến cửa hàng làm việc được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_02','V382','店长',2,'你先说说是什么原因，门店排班需要提前协调人员顶替岗位吧。','nǐ xiān shuō shuō shì shén me yuán yīn， mén diàn pái bān xū yào tí qián xié tiáo rén yuán dǐng tì gǎng wèi ba。','Em nói lý do xem nào, để bên cửa hàng còn sắp xếp người thay ca kịp thời chứ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_03','V382','阮明',3,'下周三全天进行汉语专业期末考试，从上午八点考到下午五点，全天都无法到岗，实在抱歉呢。','xià zhōu sān quán tiān jìn xíng hàn yǔ zhuān yè qī mò kǎo shì， cóng shàng wǔ bā diǎn kǎo dào xià wǔ wǔ diǎn， quán tiān dōu wú fǎ dào gǎng， shí zài bào qiàn ne。','Thứ Tư tuần sau em có kỳ thi cuối kỳ chuyên ngành tiếng Trung cả ngày, từ tám giờ sáng đến năm giờ chiều, cả ngày em không thể đến được, thật sự xin lỗi anh/chị ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_04','V382','店长',4,'学生学业优先是理所应当的，你提前一周告知，我有充足时间调整整体排班。','xué shēng xué yè yōu xiān shì lǐ suǒ yīng dāng de， nǐ tí qián yī zhōu gào zhī， wǒ yǒu chōng zú shí jiān tiáo zhěng zhěng tǐ pái bān。','Chuyện học hành của sinh viên phải ưu tiên trước là đương nhiên rồi, em báo trước một tuần thế này thì anh có đủ thời gian điều chỉnh lịch làm việc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_05','V382','阮明',5,'我担心缺一天班次，月度工时达不到门店规定标准，影响当月薪资发放。','wǒ dān xīn quē yī tiān bān cì， yuè dù gōng shí dá bú dào mén diàn guī dìng biāo zhǔn， yǐng xiǎng dàng yuè xīn zī fā fàng。','Em lo là nghỉ một ngày sẽ không đủ giờ công theo quy định của cửa hàng trong tháng, ảnh hưởng đến lương tháng này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_06','V382','店长',6,'我会安排其他空闲同事顶替你的全天班次，不用有心理负担。','wǒ huì ān pái qí tā kòng xián tóng shì dǐng tì nǐ de quán tiān bān cì， bù yòng yǒu xīn lǐ fù dān。','Anh sẽ sắp xếp đồng nghiệp khác rảnh thay ca cả ngày cho em, em đừng lo lắng gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_07','V382','阮明',7,'考完试之后，我可以主动多上两天晚班，补上本次缺失的工时。','kǎo wán shì zhī hòu， wǒ kě yǐ zhǔ dòng duō shàng liǎng tiān wǎn bān， bǔ shàng běn cì quē shī de gōng shí。','Sau khi thi xong, em có thể chủ động làm thêm hai buổi tối để bù lại phần giờ công bị thiếu lần này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_08','V382','店长',8,'不用刻意额外加班补工时，你后续正常出勤就满足月度最低工时要求。','bù yòng kè yì é wài jiā bān bǔ gōng shí， nǐ hòu xù zhèng cháng chū qín jiù mǎn zú yuè dù zuì dī gōng shí yāo qiú。','Không cần cố tình làm thêm để bù giờ công đâu, em cứ đi làm bình thường sau đó là đủ mức giờ công tối thiểu trong tháng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_09','V382','阮明',9,'太感谢店长体谅学生备考，我会提前一天完成手头所有工作交接。','tài gǎn xiè diàn zhǎng tǐ liàng xué shēng bèi kǎo， wǒ huì tí qián yī tiān wán chéng shǒu tóu suǒ yǒu gōng zuò jiāo jiē。','Em cảm ơn quản lý rất nhiều vì đã thông cảm cho việc học, em sẽ bàn giao xong hết công việc trước một ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_10','V382','店长',10,'交接不用复杂，把当日需要整理的货品清单留在收银台就行。','jiāo jiē bù yòng fù zá， bǎ dāng rì xū yào zhěng lǐ de huò pǐn qīng dān liú zài shōu yín tái jiù xíng。','Bàn giao không cần phức tạp đâu, em chỉ cần để lại danh sách hàng hóa cần sắp xếp trong ngày ở quầy thu ngân là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_11','V382','阮明',11,'考试结束后我会第一时间回门店正常上班，不耽误后续排班。','kǎo shì jié shù hòu wǒ huì dì yī shí jiān huí mén diàn zhèng cháng shàng bān， bù dān wù hòu xù pái bān。','Thi xong em sẽ quay lại làm việc bình thường ngay, không làm chậm lịch sắp xếp ca sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_12','V382','店长',12,'专心备考，不用分心担心门店工作。','zhuān xīn bèi kǎo， bù yòng fēn xīn dān xīn mén diàn gōng zuò。','Em cứ chuyên tâm ôn thi đi, đừng bận tâm về công việc ở cửa hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_13','V382','阮明',13,'我一定好好复习，不辜负您的包容。','wǒ yí dìng hǎo hǎo fù xí， bù gū fù nín de bāo róng。','Em nhất định sẽ ôn tập thật tốt, không phụ lòng bao dung của quản lý.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_14','V382','店长',14,'有任何考试变动提前跟我说，方便我重新调班。','yǒu rèn hé kǎo shì biàn dòng tí qián gēn wǒ shuō， fāng biàn wǒ chóng xīn diào bān。','Có thay đổi gì về lịch thi thì báo trước cho anh biết, để anh còn tiện sắp xếp lại ca.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_15','V382','阮明',15,'多谢店长体谅！','duō xiè diàn zhǎng tǐ liàng！','Em cảm ơn quản lý nhiều lắm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT383','S127','Hỏi rõ mức lương và hình thức trả lương',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V383','SIT383','P1','suon_se','ban_chinh_thuc',NULL,'企业发放兼职薪资仅支持国内储蓄卡，境外银行卡无法完成对公转账。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_01','V383','阮明',1,'您好，我想确认这份兼职的时薪标准和发薪渠道。','nín hǎo， wǒ xiǎng què rèn zhè fèn jiān zhí de shí xīn biāo zhǔn hé fā xīn qú dào。','Chào chị, tôi muốn xác nhận lại mức lương theo giờ và hình thức trả lương của công việc bán thời gian này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_02','V383','人事专员',2,'每小时二十二元，每月二十号银行卡统一转账哦。','měi xiǎo shí èr shí èr yuán， měi yuè èr shí hào yín háng kǎ tǒng yī zhuǎn zhàng ó。','Mỗi giờ hai mươi hai tệ, ngày hai mươi hàng tháng chuyển khoản qua thẻ ngân hàng đấy.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_03','V383','阮明',3,'薪资会扣除社保或者其他手续费之类的费用吗？','xīn zī huì kòu chú shè bǎo huò zhě qí tā shǒu xù fèi zhī lèi de fèi yòng ma？','Lương có bị trừ bảo hiểm xã hội hay các loại phí thủ tục nào khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_04','V383','人事专员',4,'学生短期兼职不缴纳社保，到手工资无扣除呢。','xué shēng duǎn qī jiān zhí bù jiǎo nà shè bǎo， dào shǒu gōng zī wú kòu chú ne。','Sinh viên làm thêm ngắn hạn không phải đóng bảo hiểm xã hội, lương nhận về không bị trừ khoản nào cả.','AM04') ON CONFLICT DO NOTHING;
